#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { chmod, copyFile, lstat, mkdir, mkdtemp, readFile, readdir, realpath, rm, stat, writeFile, } from 'node:fs/promises';
import { dirname, isAbsolute, join, resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';
import { REPO_TO_STAX_CONVERTER_VERSION } from './analyze-cli.js';
import { computeTreeDigest } from './lib/tree-digest.js';
import { qualifySeatbelt, runInQualifiedSeatbelt, } from './lib/seatbelt-runner.js';
import { validateSubAppWorkspace } from './lib/validator.js';
export const REPO_TO_STAX_TRUSTED_RUNTIME_PROTOCOL = 'repo-to-stax.trusted-runtime.v1';
const EXCLUDED_COPY_DIRECTORIES = new Set([
    '.git',
    '.next',
    '.next-edit',
    '.next-preview',
    '.turbo',
    '.cache',
    'dist',
    'node_modules',
    'out',
]);
const REQUIRED_COMMANDS = [
    ['install', ['install', '--offline', '--frozen-lockfile', '--ignore-scripts']],
    ['test', ['run', 'test']],
    ['check:slots', ['run', 'check:slots']],
    ['type-check', ['run', 'type-check']],
    ['ci:check', ['run', 'ci:check']],
    ['build', ['run', 'build']],
];
const PREFETCH_TIMEOUT_MS = 10 * 60_000;
const MAX_COPY_ENTRIES = 50_000;
const MAX_COPY_BYTES = 512 * 1024 * 1024;
const RUNTIME_GENERATED_FILES = ['next-env.d.ts', 'tsconfig.tsbuildinfo'];
const BUILD_OUTPUT_DIRECTORY = '.next-preview';
const BUILD_ARTIFACT_RELATIVE_PATH = `build-output/${BUILD_OUTPUT_DIRECTORY}`;
const REQUIRED_BUILD_FILES = [
    'BUILD_ID',
    'prerender-manifest.json',
    'routes-manifest.json',
    'build-manifest.json',
    'required-server-files.json',
];
export async function runTrustedRuntimeValidation(request) {
    const candidate = await canonicalDirectory(request.candidate, 'candidate');
    const workRoot = await canonicalDirectory(request.workRoot, 'work');
    const evidenceRoot = await canonicalDirectory(request.evidenceRoot, 'evidence');
    assertDisjointRoots(candidate, workRoot, evidenceRoot);
    const requirements = await readToolchainRequirements(candidate);
    if (process.versions.node !== requirements.nodeVersion) {
        throw new Error(`trusted runtime process must use Node ${requirements.nodeVersion}; received ${process.versions.node}`);
    }
    const pnpmCli = await canonicalPnpmCli(request.pnpmCli);
    const pnpmVersionResult = await runProcess([process.execPath, pnpmCli, '--version'], candidate, trustedEnvironment(workRoot), 30_000);
    if (pnpmVersionResult.exitCode !== 0 ||
        pnpmVersionResult.timedOut ||
        pnpmVersionResult.stdout.trim() !== requirements.pnpmVersion) {
        throw new Error(`trusted pnpm ${requirements.pnpmVersion} is unavailable`);
    }
    const conversion = await validateSubAppWorkspace(candidate, { level: 'conversion' });
    if (!conversion.ok) {
        throw new Error(`candidate must pass conversion validation: ${conversion.errors.join('; ')}`);
    }
    const candidateDigest = await computeTreeDigest(candidate);
    const runRoot = await mkdtemp(join(workRoot, 'run-'));
    const disposableWorkspace = join(runRoot, 'workspace');
    const dependencyStore = join(evidenceRoot, 'dependency-store');
    let disposableWorkspaceRemoved = false;
    let scriptsExecuted = false;
    let qualification = {
        qualified: false,
        profileDigest: '',
        probes: {},
    };
    let dependencyPrefetch = {
        ok: false,
        exitCode: null,
        timedOut: false,
        stdout: summarizeOutput(''),
        stderr: summarizeOutput(''),
    };
    const commands = [];
    let buildArtifact = null;
    let failurePhase = null;
    try {
        await secureCopyCandidate(candidate, disposableWorkspace);
        if ((await computeTreeDigest(disposableWorkspace)) !== candidateDigest) {
            throw new Error('disposable candidate copy does not match the confirmed tree digest');
        }
        const runtimeStableDigest = await computeRuntimeStableTreeDigest(disposableWorkspace);
        await assertSafeLockfile(disposableWorkspace);
        await mkdir(dependencyStore, { recursive: true, mode: 0o700 });
        const prefetch = await runProcess([
            process.execPath,
            pnpmCli,
            'fetch',
            '--frozen-lockfile',
            '--ignore-scripts',
            '--store-dir',
            dependencyStore,
            '--registry=https://registry.npmjs.org/',
        ], disposableWorkspace, trustedEnvironment(runRoot), PREFETCH_TIMEOUT_MS);
        dependencyPrefetch = {
            ok: prefetch.exitCode === 0 && !prefetch.timedOut && prefetch.signal === null,
            exitCode: prefetch.exitCode,
            timedOut: prefetch.timedOut,
            stdout: summarizeOutput(prefetch.stdout),
            stderr: summarizeOutput(prefetch.stderr),
        };
        if (!dependencyPrefetch.ok) {
            failurePhase = 'dependency-prefetch';
        }
        else {
            const qualified = await qualifySeatbelt({
                workspaceRoot: disposableWorkspace,
                evidenceRoot,
                allowLoopback: false,
            });
            qualification = {
                qualified: qualified.qualified,
                profileDigest: qualified.profileDigest,
                probes: qualified.probes,
            };
            if (!qualified.qualified) {
                failurePhase = 'seatbelt-qualification';
            }
            else {
                for (const [id, pnpmArgs] of REQUIRED_COMMANDS) {
                    scriptsExecuted = true;
                    const command = await runInQualifiedSeatbelt([
                        process.execPath,
                        pnpmCli,
                        ...pnpmArgs,
                        ...(id === 'install' ? ['--store-dir', dependencyStore] : []),
                    ], {
                        workspaceRoot: disposableWorkspace,
                        evidenceRoot,
                        qualificationDigest: qualified.profileDigest,
                        env: {
                            BROWSERSLIST_ROOT_PATH: disposableWorkspace,
                            NO_COLOR: '1',
                            ...(id === 'build' ? { TAKU_RUNTIME_KIND: 'preview' } : {}),
                        },
                        timeoutMs: request.commandTimeoutMs,
                    });
                    commands.push(commandEvidence(id, command));
                    if (command.exitCode !== 0 || command.signal !== null || command.timedOut) {
                        failurePhase = id;
                        break;
                    }
                }
            }
        }
        if (failurePhase === null && commands.length === REQUIRED_COMMANDS.length) {
            try {
                buildArtifact = await preserveTrustedBuildArtifact({
                    workspaceRoot: disposableWorkspace,
                    evidenceRoot,
                });
            }
            catch {
                failurePhase = 'build-artifact';
            }
        }
        if ((await computeRuntimeStableTreeDigest(disposableWorkspace)) !==
            runtimeStableDigest) {
            failurePhase ??= 'candidate-tree-mutated';
        }
    }
    finally {
        await rm(runRoot, { recursive: true, force: true });
        disposableWorkspaceRemoved = true;
        await rm(dependencyStore, { recursive: true, force: true }).catch(() => undefined);
    }
    const originalCandidateUnchanged = (await computeTreeDigest(candidate)) === candidateDigest;
    if (!originalCandidateUnchanged)
        failurePhase ??= 'original-candidate-mutated';
    const allCommandsPassed = commands.length === REQUIRED_COMMANDS.length &&
        commands.every(command => command.exitCode === 0 && command.signal === null && !command.timedOut);
    return {
        protocol: REPO_TO_STAX_TRUSTED_RUNTIME_PROTOCOL,
        converterVersion: REPO_TO_STAX_CONVERTER_VERSION,
        ok: dependencyPrefetch.ok &&
            qualification.qualified &&
            allCommandsPassed &&
            buildArtifact !== null &&
            originalCandidateUnchanged &&
            disposableWorkspaceRemoved &&
            failurePhase === null,
        workspaceRoot: candidate,
        candidateDigest,
        toolchain: requirements,
        qualification,
        dependencyPrefetch,
        commands,
        failurePhase,
        originalCandidateUnchanged,
        disposableWorkspaceRemoved,
        scriptsExecutedInDisposableWorkspace: scriptsExecuted,
        buildArtifact,
        publishStarted: false,
        evidenceRoot,
    };
}
export async function preserveTrustedBuildArtifact(input) {
    const sourceRoot = join(input.workspaceRoot, BUILD_OUTPUT_DIRECTORY);
    for (const required of REQUIRED_BUILD_FILES) {
        const metadata = await lstat(join(sourceRoot, required));
        if (!metadata.isFile() || metadata.isSymbolicLink()) {
            throw new Error(`trusted preview build is missing ${required}`);
        }
    }
    const destinationRoot = join(input.evidenceRoot, BUILD_ARTIFACT_RELATIVE_PATH);
    const existing = await lstat(destinationRoot).catch(() => null);
    if (existing)
        throw new Error('trusted build artifact destination already exists');
    await mkdir(join(input.evidenceRoot, 'build-output'), { mode: 0o700 });
    try {
        await copyArtifactTree(sourceRoot, destinationRoot);
    }
    catch (error) {
        await rm(join(input.evidenceRoot, 'build-output'), { recursive: true, force: true });
        throw error;
    }
    const [sourceSummary, destinationSummary] = await Promise.all([
        summarizeArtifactTree(sourceRoot),
        summarizeArtifactTree(destinationRoot),
    ]);
    if (sourceSummary.treeDigest !== destinationSummary.treeDigest ||
        sourceSummary.fileCount !== destinationSummary.fileCount ||
        sourceSummary.sizeBytes !== destinationSummary.sizeBytes) {
        throw new Error('trusted build artifact copy failed integrity verification');
    }
    const artifact = {
        schemaVersion: 'taku.subapp-runtime-build.v1',
        buildOutputDir: BUILD_OUTPUT_DIRECTORY,
        evidenceRelativePath: BUILD_ARTIFACT_RELATIVE_PATH,
        ...destinationSummary,
    };
    await writeFile(join(input.evidenceRoot, 'build-artifact.json'), `${JSON.stringify(artifact, null, 2)}\n`, { encoding: 'utf8', mode: 0o600 });
    return artifact;
}
export async function summarizeArtifactTree(root) {
    const hash = createHash('sha256');
    let fileCount = 0;
    let sizeBytes = 0;
    async function walk(relativeRoot) {
        const children = await readdir(join(root, relativeRoot), { withFileTypes: true });
        children.sort((left, right) => left.name.localeCompare(right.name));
        for (const child of children) {
            const relativePath = join(relativeRoot, child.name).replace(/\\/g, '/');
            const absolutePath = join(root, relativePath);
            const metadata = await lstat(absolutePath);
            if (metadata.isSymbolicLink())
                throw new Error('trusted build artifact contains a symlink');
            if (metadata.isDirectory()) {
                await walk(relativePath);
                continue;
            }
            if (!metadata.isFile())
                throw new Error('trusted build artifact contains an unsupported entry');
            fileCount += 1;
            sizeBytes += metadata.size;
            if (fileCount > MAX_COPY_ENTRIES || sizeBytes > MAX_COPY_BYTES) {
                throw new Error('trusted build artifact exceeds the copy limit');
            }
            const content = await readFile(absolutePath);
            hash.update(relativePath);
            hash.update('\0');
            hash.update(String(metadata.size));
            hash.update('\0');
            hash.update(content);
            hash.update('\0');
        }
    }
    const rootMetadata = await stat(root);
    if (!rootMetadata.isDirectory())
        throw new Error('trusted build artifact root is not a directory');
    await walk('');
    if (fileCount === 0 || sizeBytes === 0)
        throw new Error('trusted build artifact is empty');
    return {
        treeDigest: `sha256:${hash.digest('hex')}`,
        fileCount,
        sizeBytes,
    };
}
async function copyArtifactTree(sourceRoot, destinationRoot) {
    let entries = 0;
    let bytes = 0;
    await mkdir(destinationRoot, { recursive: false, mode: 0o700 });
    async function copyDirectory(source, destination) {
        const children = await readdir(source, { withFileTypes: true });
        children.sort((left, right) => left.name.localeCompare(right.name));
        for (const child of children) {
            entries += 1;
            if (entries > MAX_COPY_ENTRIES)
                throw new Error('trusted build artifact entry limit exceeded');
            const from = join(source, child.name);
            const to = join(destination, child.name);
            const metadata = await lstat(from);
            if (metadata.isSymbolicLink())
                throw new Error('trusted build artifact contains a symlink');
            if (metadata.isDirectory()) {
                await mkdir(to, { mode: metadata.mode & 0o777 });
                await copyDirectory(from, to);
            }
            else if (metadata.isFile()) {
                bytes += metadata.size;
                if (bytes > MAX_COPY_BYTES)
                    throw new Error('trusted build artifact byte limit exceeded');
                await copyFile(from, to);
                await chmod(to, metadata.mode & 0o777);
            }
            else {
                throw new Error('trusted build artifact contains an unsupported entry');
            }
        }
    }
    await copyDirectory(sourceRoot, destinationRoot);
}
export function computeRuntimeStableTreeDigest(root) {
    return computeTreeDigest(root, { exclude: RUNTIME_GENERATED_FILES });
}
export async function readToolchainRequirements(candidate) {
    const [nvmrc, packageContents] = await Promise.all([
        readFile(join(candidate, '.nvmrc'), 'utf8'),
        readFile(join(candidate, 'package.json'), 'utf8'),
    ]);
    if (!/^\d+\.\d+\.\d+\n$/.test(nvmrc)) {
        throw new Error('candidate .nvmrc must contain one exact Node version with LF');
    }
    const packageJson = JSON.parse(packageContents);
    const packageManager = String(packageJson.packageManager ?? '');
    const match = packageManager.match(/^pnpm@(\d+\.\d+\.\d+)$/);
    if (!match?.[1])
        throw new Error('candidate must pin one exact pnpm version');
    return { nodeVersion: nvmrc.trim(), pnpmVersion: match[1] };
}
async function secureCopyCandidate(source, target) {
    let entries = 0;
    let bytes = 0;
    await mkdir(target, { mode: 0o700 });
    async function copyDirectory(sourceRoot, targetRoot) {
        const children = await readdir(sourceRoot, { withFileTypes: true });
        children.sort((left, right) => left.name.localeCompare(right.name));
        for (const child of children) {
            if (child.isDirectory() && EXCLUDED_COPY_DIRECTORIES.has(child.name))
                continue;
            entries += 1;
            if (entries > MAX_COPY_ENTRIES)
                throw new Error('candidate copy entry limit exceeded');
            const from = join(sourceRoot, child.name);
            const to = join(targetRoot, child.name);
            const metadata = await lstat(from);
            if (metadata.isSymbolicLink())
                throw new Error(`candidate contains a symlink: ${from}`);
            if (metadata.isDirectory()) {
                await mkdir(to, { mode: 0o700 });
                await copyDirectory(from, to);
            }
            else if (metadata.isFile()) {
                bytes += metadata.size;
                if (bytes > MAX_COPY_BYTES)
                    throw new Error('candidate copy byte limit exceeded');
                await copyFile(from, to);
                await chmod(to, metadata.mode & 0o777);
            }
            else {
                throw new Error(`candidate contains an unsupported filesystem entry: ${from}`);
            }
        }
    }
    await copyDirectory(source, target);
}
async function assertSafeLockfile(workspace) {
    const lockfile = await readFile(join(workspace, 'pnpm-lock.yaml'), 'utf8');
    if (Buffer.byteLength(lockfile) > 20 * 1024 * 1024) {
        throw new Error('pnpm lockfile exceeds the trusted prefetch limit');
    }
    const unsafe = lockfile.split(/\r?\n/).find(line => /^\s*(?:tarball|specifier|resolution):\s*(?:https?:|git\+|git:|file:|link:)/i.test(line));
    if (unsafe)
        throw new Error('pnpm lockfile contains a non-registry dependency locator');
}
async function canonicalDirectory(input, label) {
    if (!isAbsolute(input))
        throw new Error(`${label} root must be absolute`);
    const normalized = resolve(input);
    const canonical = await realpath(normalized);
    const metadata = await lstat(canonical);
    if (canonical !== normalized || !metadata.isDirectory() || metadata.isSymbolicLink()) {
        throw new Error(`${label} root must be a canonical directory`);
    }
    return canonical;
}
async function canonicalPnpmCli(input) {
    if (!isAbsolute(input))
        throw new Error('pnpm CLI path must be absolute');
    const canonical = await realpath(resolve(input));
    const metadata = await lstat(canonical);
    const nodeRuntimeRoot = dirname(dirname(process.execPath));
    if (!metadata.isFile() || !isWithin(canonical, nodeRuntimeRoot)) {
        throw new Error('pnpm CLI must be a regular file inside the trusted Node runtime');
    }
    return canonical;
}
function assertDisjointRoots(candidate, workRoot, evidenceRoot) {
    if (isWithin(workRoot, candidate) ||
        isWithin(evidenceRoot, candidate) ||
        isWithin(candidate, workRoot) ||
        isWithin(candidate, evidenceRoot) ||
        isWithin(workRoot, evidenceRoot) ||
        isWithin(evidenceRoot, workRoot)) {
        throw new Error('candidate, work, and evidence roots must be disjoint');
    }
}
function isWithin(candidate, root) {
    return candidate === root || candidate.startsWith(`${root}${sep}`);
}
function trustedEnvironment(runtimeRoot) {
    return {
        PATH: [dirname(process.execPath), '/usr/bin', '/bin', '/usr/sbin', '/sbin'].join(':'),
        HOME: runtimeRoot,
        TMPDIR: `${runtimeRoot}${sep}`,
        CI: '1',
        NO_COLOR: '1',
    };
}
function runProcess(command, cwd, env, timeoutMs) {
    return new Promise((resolvePromise, rejectPromise) => {
        const child = spawn(command[0], command.slice(1), {
            cwd,
            env,
            detached: true,
            stdio: ['ignore', 'pipe', 'pipe'],
        });
        let stdout = '';
        let stderr = '';
        let timedOut = false;
        let settled = false;
        child.stdout.setEncoding('utf8').on('data', chunk => { stdout += chunk; });
        child.stderr.setEncoding('utf8').on('data', chunk => { stderr += chunk; });
        child.once('error', error => {
            if (settled)
                return;
            settled = true;
            clearTimeout(timer);
            rejectPromise(error);
        });
        child.once('close', (exitCode, signal) => {
            if (settled)
                return;
            settled = true;
            clearTimeout(timer);
            resolvePromise({ exitCode, signal, stdout, stderr, timedOut });
        });
        const timer = setTimeout(() => {
            timedOut = true;
            if (child.pid !== undefined) {
                try {
                    process.kill(-child.pid, 'SIGKILL');
                }
                catch {
                    child.kill('SIGKILL');
                }
            }
        }, timeoutMs);
    });
}
function commandEvidence(id, result) {
    const failed = result.exitCode !== 0 || result.signal !== null || result.timedOut;
    return {
        id,
        exitCode: result.exitCode,
        signal: result.signal,
        timedOut: result.timedOut,
        evidencePath: result.evidencePath,
        ...(failed
            ? { diagnostic: sanitizeDiagnostic(`${result.stdout}\n${result.stderr}`) }
            : {}),
    };
}
function sanitizeDiagnostic(value) {
    return value
        .replace(/\u001B\]8;;[^\u001B]*\u001B\\/g, '')
        .replace(/\u001B\[[0-?]*[ -/]*[@-~]/g, '')
        .replace(/((?:api[_-]?key|authorization|bearer|credential|password|private[_-]?key|secret|session|token)\s*[=:]\s*)[^\s,;]+/gi, '$1[REDACTED]')
        .replace(/-----BEGIN [^-]+ PRIVATE KEY-----[\s\S]*?-----END [^-]+ PRIVATE KEY-----/g, '[REDACTED PRIVATE KEY]')
        .slice(0, 64_000)
        .trim();
}
function summarizeOutput(value) {
    return {
        byteLength: Buffer.byteLength(value),
        sha256: `sha256:${createHash('sha256').update(value).digest('hex')}`,
    };
}
async function main() {
    const [command, candidate, workRoot, evidenceRoot, pnpmCli, timeout] = process.argv.slice(2);
    if (command !== 'check' ||
        !candidate ||
        !workRoot ||
        !evidenceRoot ||
        !pnpmCli ||
        process.argv.slice(2).length > 6) {
        throw new Error('Usage: runtime-cli check <candidate> <work-root> <evidence-root> <pnpm-cli> [timeout-ms]');
    }
    const commandTimeoutMs = timeout === undefined ? undefined : Number(timeout);
    const result = await runTrustedRuntimeValidation({
        candidate,
        workRoot,
        evidenceRoot,
        pnpmCli,
        ...(commandTimeoutMs === undefined ? {} : { commandTimeoutMs }),
    });
    process.stdout.write(`${JSON.stringify(result)}\n`);
    if (!result.ok)
        process.exitCode = 1;
}
if (process.argv[1] &&
    import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
    main().catch(error => {
        process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
        process.exitCode = 1;
    });
}
